[CmdletBinding()]
param(
    [string]$RepoRoot = "."
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$ExpectedHead = "d283ff20fa807822268a88713041c73c14798b32"
$RepoRoot = (Resolve-Path $RepoRoot).Path
Set-Location $RepoRoot

function Assert-LastExitCode([string]$Step) {
    if ($LASTEXITCODE -ne 0) {
        throw "$Step fallo con codigo de salida $LASTEXITCODE."
    }
}

function Decode-Utf8Base64([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

function Write-Utf8NoBomLf([string]$RelativePath, [string]$Content) {
    $path = Join-Path $RepoRoot $RelativePath
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir -PathType Container)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }

    $normalized = $Content.Replace("`r`n", "`n").Replace("`r", "`n")
    [System.IO.File]::WriteAllText($path, $normalized, [System.Text.UTF8Encoding]::new($false))
}

function Read-Normalized([string]$RelativePath) {
    $path = Join-Path $RepoRoot $RelativePath
    if (-not (Test-Path $path -PathType Leaf)) {
        throw "Falta $RelativePath."
    }

    return ([System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)).Replace("`r`n", "`n").Replace("`r", "`n")
}

function Replace-ExactOnce(
    [string]$RelativePath,
    [string]$OldText,
    [string]$NewText,
    [string]$Description
) {
    $content = Read-Normalized $RelativePath
    $first = $content.IndexOf($OldText, [System.StringComparison]::Ordinal)
    if ($first -lt 0) {
        throw "No se encontro el bloque esperado para $Description en $RelativePath."
    }

    $second = $content.IndexOf($OldText, $first + $OldText.Length, [System.StringComparison]::Ordinal)
    if ($second -ge 0) {
        throw "El bloque de $Description aparece mas de una vez en $RelativePath."
    }

    $updated = $content.Remove($first, $OldText.Length).Insert($first, $NewText)
    Write-Utf8NoBomLf $RelativePath $updated
    Write-Host "OK: $Description"
}

function Append-Once(
    [string]$RelativePath,
    [string]$Marker,
    [string]$Text,
    [string]$Description
) {
    $content = Read-Normalized $RelativePath
    if ($content.Contains($Marker)) {
        Write-Host "OK: $Description ya estaba aplicado."
        return
    }

    Write-Utf8NoBomLf $RelativePath ($content.TrimEnd() + "`n`n" + $Text.Trim() + "`n")
    Write-Host "OK: $Description"
}

Write-Host "BL-MVP-067 v20 v2: UX de expediente/derechos + volver arriba + correccion de verifier BL064..."

$head = (git rev-parse HEAD).Trim()
Assert-LastExitCode "Leer HEAD"
if ($head -cne $ExpectedHead) {
    throw "Este correctivo requiere HEAD exacto $ExpectedHead y encontro $head."
}

$branch = (git branch --show-current).Trim()
Assert-LastExitCode "Leer rama"
if ($branch -cne "main") {
    throw "Este correctivo debe aplicarse sobre main."
}

$staged = @(git diff --cached --name-only)
Assert-LastExitCode "Revisar staging"
if ($staged.Count -gt 0) {
    throw "El staging debe estar vacio antes de aplicar el correctivo."
}

$dirty = @(git diff --name-only)
Assert-LastExitCode "Revisar cambios tracked"
$untracked = @(git ls-files --others --exclude-standard)
Assert-LastExitCode "Revisar untracked"

# El instalador temporal vive dentro de scripts/ por diseño y, por tanto,
# aparece como untracked. No debe bloquearse a sí mismo. Solo se permiten
# exactamente los nombres de esta ronda; cualquier otro untracked sí aborta.
$allowedInstallerPaths = @(
    "scripts/apply-bl-mvp-067-v20-ux-continuation.ps1",
    "scripts/apply-bl-mvp-067-v20-ux-continuation-v2.ps1"
)
$unexpectedUntracked = @(
    $untracked | Where-Object {
        $normalized = $_.Replace("\", "/")
        $allowedInstallerPaths -notcontains $normalized
    }
)

if ($dirty.Count -gt 0 -or $unexpectedUntracked.Count -gt 0) {
    if ($dirty.Count -gt 0) {
        Write-Host "Cambios tracked inesperados:" -ForegroundColor Yellow
        $dirty | ForEach-Object { Write-Host " - $_" -ForegroundColor Yellow }
    }
    if ($unexpectedUntracked.Count -gt 0) {
        Write-Host "Untracked inesperados:" -ForegroundColor Yellow
        $unexpectedUntracked | ForEach-Object { Write-Host " - $_" -ForegroundColor Yellow }
    }
    throw "El working tree debe estar limpio salvo por el instalador temporal de v20."
}

